**The bug:** The condition `decoded.exp < Date.now() / 1000` uses strict less-than, so a token where `exp === currentTime` slips through as valid. It should be `<=`.

There's also a second issue: `jwt.verify()` already throws `TokenExpiredError` for expired tokens, so the manual check is redundant — and its off-by-one makes it inconsistent with `jsonwebtoken`'s own expiry logic. The catch block also swallows all errors with the same generic message, making it impossible to distinguish expired from tampered tokens.

**Fixed version:**

```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    // jwt.verify already rejects expired tokens (exp <= now), including exact boundary
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }
    if (err.name === 'JsonWebTokenError') {
      return res.status(401).json({ error: 'Invalid token' });
    }
    // Unexpected error (e.g. misconfigured secret) — don't leak details
    return res.status(500).json({ error: 'Authentication error' });
  }
}

module.exports = authMiddleware;
```

**Summary of changes:**

| Issue | Before | After |
|---|---|---|
| Boundary bug | `exp < now` accepts `exp === now` | Removed — `jwt.verify` uses `exp <= now` correctly |
| Redundant check | Manual expiry check after `jwt.verify` | Removed; trust the library |
| Error handling | All errors → same 401 message | `TokenExpiredError` vs `JsonWebTokenError` vs unexpected 500 |
